-- Massa exclusivamente sintética para demonstração e QA local.
-- Ative com MEDFLOW_FLYWAY_LOCATIONS=classpath:db/migration,classpath:db/demo.

ON CONFLICT (id) DO UPDATE SET
nome = EXCLUDED.nome,
endereco = EXCLUDED.endereco,
ativo = EXCLUDED.ativo;

ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, ativo = EXCLUDED.ativo;

ON CONFLICT (id) DO UPDATE SET
nome = EXCLUDED.nome,
ativo = EXCLUDED.ativo;

ON CONFLICT (id) DO UPDATE SET
nome = EXCLUDED.nome,
crm_numero = EXCLUDED.crm_numero,
crm_uf = EXCLUDED.crm_uf,
subject = EXCLUDED.subject,
ativo = EXCLUDED.ativo;

ON CONFLICT DO NOTHING;

ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, subject = EXCLUDED.subject;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;
